/**
 * Typed contract addresses for the deployed AMM stack.
 *
 * The addresses are generated by `script/Deploy.s.sol` into `deployments/<chainid>.json`.
 * Vite inlines the JSON at build time through the import below, so the frontend never has to
 * fetch a config file at runtime and a stale deployment cannot silently desync from the UI.
 */
import deployment from "../../../deployments/31337.json";

export interface Deployment {
  factory: `0x${string}`;
  router: `0x${string}`;
  oracle: `0x${string}`;
  arb: `0x${string}`;
  weth: `0x${string}`;
  tokenA: `0x${string}`;
  tokenB: `0x${string}`;
}

const raw = deployment as Record<string, string>;

export const addresses: Deployment = {
  factory: raw.factory as `0x${string}`,
  router: raw.router as `0x${string}`,
  oracle: raw.oracle as `0x${string}`,
  arb: raw.arb as `0x${string}`,
  weth: raw.weth as `0x${string}`,
  tokenA: raw.tokenA as `0x${string}`,
  tokenB: raw.tokenB as `0x${string}`,
};

/** Anvil's deterministic chain id. */
export const LOCAL_CHAIN_ID = 31337;
